<?php
declare(strict_types=1);
use DigiForge\Orders\PersonalizationCurrentness;
use DigiForge\POD\{CustomerEditorRepository,CustomerPhotoSelection};
// Intentionally failing source-owner reproductions; excluded from the acceptance suite.
require_once dirname(__DIR__,4).'/tests/wordpress/CustomerPhotoHeldIntegrationTest.php';
final class CustomerPhotoOwnerCurrentReadFailureReproTest extends CustomerPhotoHeldIntegrationTest {
 public function testActualProducerSelectionCannotRemainOldAcrossCommittedSamePixelRevision():void {
  $f=$this->photo();$actor=get_current_user_id();$photo=new CustomerPhotoSelection();global $wpdb;$primary=$wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->set_prefix($primary->prefix);$modes=['READ-COMMITTED'=>'READ COMMITTED','REPEATABLE-READ'=>'REPEATABLE READ','READ-UNCOMMITTED'=>'READ UNCOMMITTED','SERIALIZABLE'=>'SERIALIZABLE'];$prior=strtoupper((string)$primary->get_var('SELECT @@session.tx_isolation'));self::assertArrayHasKey($prior,$modes);$next=null;
  try {self::assertNotFalse($primary->query('COMMIT'));self::assertNotFalse($primary->query('SET autocommit=1'));self::assertNotFalse($primary->query('SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ'));self::assertNotFalse($primary->query('START TRANSACTION WITH CONSISTENT SNAPSHOT'));$first=PrintifyApiApprovalFixture::checked($photo->forOrder('personalized_pod',$f['order'],$f['line']));self::assertSame($f['selection']['sha256'],$first['sha256']);
   $wpdb=$other;self::assertNotFalse($other->query('SET SESSION innodb_lock_wait_timeout=2'));wp_set_current_user($f['customer']);$request=$f['request'];$request['request_key']='two-connection-same-photo';$request['expected_head']=$f['version']['sha256'];$version=PrintifyApiApprovalFixture::checked((new CustomerEditorRepository())->upload($f['session'],$request));$next=PrintifyApiApprovalFixture::checked($photo->submit($f['session'],$version['sha256'],1));wp_set_current_user($actor);PrintifyApiApprovalFixture::checked($photo->review($f['session'],$next['sha256'],2,'APPROVED','Synthetic independently committed second selection'));self::assertSame('0',(string)$other->get_var('SELECT @@session.in_transaction'));$fresh=PrintifyApiApprovalFixture::checked($photo->forOrder('personalized_pod',$f['order'],$f['line']));self::assertSame($next['sha256'],$fresh['sha256']);self::assertSame($f['selection']['submission_id'],$next['submission_id']);self::assertNotSame($f['selection']['sha256'],$next['sha256']);
   $wpdb=$primary;$stale=$photo->forOrder('personalized_pod',$f['order'],$f['line']);self::assertTrue(is_wp_error($stale)||(is_array($stale)&&$stale['sha256']===$next['sha256']),'An authoritative current selection must not return epoch1 from an old real RR snapshot after epoch2 committed on another connection.');
  }finally{$wpdb=$primary;$primary->query('ROLLBACK');$primary->query('SET autocommit=1');$primary->query('SET SESSION TRANSACTION ISOLATION LEVEL '.$modes[$prior]);$other->query('ROLLBACK');$other->close();wp_set_current_user($actor);}
 }
 public function testLegacyNullCannotRemainAfterFirstManagedSelectionCommitted():void {
  $f=$this->photo(false);$actor=get_current_user_id();global $wpdb;$primary=$wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->set_prefix($primary->prefix);$modes=['READ-COMMITTED'=>'READ COMMITTED','REPEATABLE-READ'=>'REPEATABLE READ','READ-UNCOMMITTED'=>'READ UNCOMMITTED','SERIALIZABLE'=>'SERIALIZABLE'];$prior=strtoupper((string)$primary->get_var('SELECT @@session.tx_isolation'));self::assertArrayHasKey($prior,$modes);
  try{$primary->query('COMMIT');$primary->query('SET autocommit=1');$primary->query('SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ');$primary->query('START TRANSACTION WITH CONSISTENT SNAPSHOT');self::assertNull((new CustomerPhotoSelection())->resolveForOrder('personalized_pod',$f['order'],$f['line']));self::assertNotWPError((new PersonalizationCurrentness())->forOrder($f['order']));
   $wpdb=$other;$other->query('SET SESSION innodb_lock_wait_timeout=2');wp_set_current_user($f['customer']);$version=PrintifyApiApprovalFixture::checked((new CustomerEditorRepository())->upload($f['session'],$f['request']));$selection=PrintifyApiApprovalFixture::checked((new CustomerPhotoSelection())->submit($f['session'],$version['sha256'],0));wp_set_current_user($actor);PrintifyApiApprovalFixture::checked((new CustomerPhotoSelection())->review($f['session'],$selection['sha256'],1,'APPROVED','Synthetic first independently committed managed selection'));self::assertSame('0',(string)$other->get_var('SELECT @@session.in_transaction'));self::assertSame($selection['sha256'],PrintifyApiApprovalFixture::checked((new CustomerPhotoSelection())->resolveForOrder('personalized_pod',$f['order'],$f['line']))['sha256']);
   $wpdb=$primary;self::assertWPError((new PersonalizationCurrentness())->forOrder($f['order']),'An old nullable legacy snapshot must not authorize legacy input after the first managed selection commits.');
  }finally{$wpdb=$primary;$primary->query('ROLLBACK');$primary->query('SET autocommit=1');$primary->query('SET SESSION TRANSACTION ISOLATION LEVEL '.$modes[$prior]);$other->query('ROLLBACK');$other->close();wp_set_current_user($actor);}
 }
}
